select.if:
SELECT ftl.flow_id,ftl.template_id,ftl.cur_link,ftl.link_type,ftl.pre_link,ftl.next_link,flc.link_name, flic.alarm_flow_id,afc.alarm_flow_name,flic.msg_notify_type,flic.user_type,flic.id as attr_id,flic.notify_admin_flag,flic.leader_flag FROM vm_flow_template_link ftl INNER JOIN vm_flow_link_config flc ON ftl.cur_link = flc.link_id INNER JOIN vm_alarm_flow_config afc ON ftl.template_id = afc.template_id LEFT JOIN vm_flow_link_attr flic ON ftl.cur_link = flic.link_id and flic.alarm_flow_id=afc.id WHERE afc.id = #{alarmFlowId}
AND ftl.cur_link = #{linkId}
AND ftl.real_link_type = #{realLinkType} and ftl.link_type='1'

mapper.select:
SELECT ft.template_id,ft.tenant_id,ft.flow_name,ft.init_source,afc.app_ver_code,afc.industry_code,tat.alarm_flow_id
FROM vm_flow_template ft
INNER JOIN vm_flow_template_alarm_type tat ON ft.template_id = tat.template_id
INNER JOIN vm_alarm_flow_config afc on afc.id = tat.alarm_flow_id
WHERE ft.delete_flag = 0 and afc.delete_flag = 0
AND tat.delete_flag = 0 AND  tat.warning_source = #{warningSource} AND tat.alarm_type = #{alarmType}
AND afc.tenant_id = #{tenantId}

    AND afc.app_ver_code = #{appVerCode}


    AND afc.industry_code = #{industryCode}

limit 1

SELECT template_id,tenant_id,flow_name,init_source,app_ver_code,industry_code FROM vm_flow_template
WHERE delete_flag = 0 AND `status` = '1'

    AND flow_type = #{flowType}


    AND app_ver_code is null AND industry_code is null


    AND app_ver_code = #{appVerCode}


    AND industry_code = #{industryCode}


    AND init_source like CONCAT('%', #{initSource}, '%')


    AND tenant_id = #{tenantId}
